import numpy as np
from scipy.optimize import minimize

def objective(vars):
    x, y, z, w = vars
    return y/(16*x**3 + 1) + z/(16*y**3 + 1) + w/(16*z**3 + 1) + x/(16*w**3 + 1)

cons = ({'type': 'eq', 'fun': lambda vars: np.sum(vars) - 1})
bounds = [(0, 1), (0, 1), (0, 1), (0, 1)]

min_val = float('inf')
best_vars = None

# Try a grid of starting points
for i in np.linspace(0, 1, 10):
    for j in np.linspace(0, 1, 10):
        for k in np.linspace(0, 1, 10):
            l = 1 - i - j - k
            if l >= 0:
                res = minimize(objective, [i, j, k, l], bounds=bounds, constraints=cons)
                if res.success and res.fun < min_val:
                    min_val = res.fun
                    best_vars = res.x

print(f"Min value: {min_val}")
print(f"Best vars: {best_vars}")
